CREATE INDEX inventory_ledger_entry_inventory_item_variant_id_ix ON inventory.inventory_ledger_entry (tenant_id, inventory_item_variant_id);
ALTER TABLE inventory.inventory_ledger_entry ADD CONSTRAINT inventory_ledger_entry_location_id_fk FOREIGN KEY (tenant_id, property_id, location_id) REFERENCES resources.location (tenant_id, property_id, location_id) ON DELETE RESTRICT;
CREATE INDEX inventory_ledger_entry_location_id_ix ON inventory.inventory_ledger_entry (tenant_id, property_id, location_id);
ALTER TABLE inventory.inventory_ledger_entry ADD CONSTRAINT inventory_ledger_entry_tenant_fk FOREIGN KEY (tenant_id) REFERENCES core.tenant (tenant_id);
ALTER TABLE inventory.inventory_ledger_entry ADD CONSTRAINT inventory_ledger_entry_property_fk FOREIGN KEY (tenant_id, property_id) REFERENCES core.property (tenant_id, property_id);
ALTER TABLE inventory.laundry_batch ADD CONSTRAINT laundry_batch_dispatch_location_id_fk FOREIGN KEY (tenant_id, property_id, dispatch_location_id) REFERENCES resources.location (tenant_id, property_id, location_id) ON DELETE RESTRICT;
CREATE INDEX laundry_batch_dispatch_location_id_ix ON inventory.laundry_batch (tenant_id, property_id, dispatch_location_id);
