CREATE INDEX laundry_batch_return_location_id_ix ON inventory.laundry_batch (tenant_id, property_id, return_location_id);
ALTER TABLE inventory.laundry_batch ADD CONSTRAINT laundry_batch_tenant_fk FOREIGN KEY (tenant_id) REFERENCES core.tenant (tenant_id);
ALTER TABLE inventory.laundry_batch ADD CONSTRAINT laundry_batch_property_fk FOREIGN KEY (tenant_id, property_id) REFERENCES core.property (tenant_id, property_id);
ALTER TABLE inventory.service_supply ADD CONSTRAINT service_supply_service_id_fk FOREIGN KEY (tenant_id, service_id) REFERENCES catalog.service (tenant_id, service_id) ON DELETE RESTRICT;
CREATE INDEX service_supply_service_id_ix ON inventory.service_supply (tenant_id, service_id);
ALTER TABLE inventory.service_supply ADD CONSTRAINT service_supply_inventory_item_variant_id_fk FOREIGN KEY (tenant_id, inventory_item_variant_id) REFERENCES inventory.inventory_item_variant (tenant_id, inventory_item_variant_id) ON DELETE RESTRICT;
CREATE INDEX service_supply_inventory_item_variant_id_ix ON inventory.service_supply (tenant_id, inventory_item_variant_id);
ALTER TABLE inventory.service_supply ADD CONSTRAINT service_supply_tenant_fk FOREIGN KEY (tenant_id) REFERENCES core.tenant (tenant_id);
