CREATE TRIGGER inventory_item_touch BEFORE UPDATE ON inventory.inventory_item FOR EACH ROW EXECUTE FUNCTION core.touch_versioned();
CREATE TRIGGER inventory_item_variant_touch BEFORE UPDATE ON inventory.inventory_item_variant FOR EACH ROW EXECUTE FUNCTION core.touch_versioned();
CREATE TRIGGER inventory_location_balance_touch BEFORE UPDATE ON inventory.inventory_location_balance FOR EACH ROW EXECUTE FUNCTION core.touch();
CREATE TRIGGER inventory_ledger_entry_append_only BEFORE UPDATE OR DELETE ON inventory.inventory_ledger_entry FOR EACH ROW EXECUTE FUNCTION core.forbid_mutation();
DO $$ BEGIN PERFORM core.ensure_monthly_partitions('inventory.inventory_ledger_entry'::regclass, (date_trunc('month', now() AT TIME ZONE 'UTC') - interval '1 month')::date, 4); END $$;
CREATE TABLE inventory.inventory_ledger_entry_default PARTITION OF inventory.inventory_ledger_entry DEFAULT;
CREATE TRIGGER laundry_batch_touch BEFORE UPDATE ON inventory.laundry_batch FOR EACH ROW EXECUTE FUNCTION core.touch_versioned();
CREATE TRIGGER service_supply_touch BEFORE UPDATE ON inventory.service_supply FOR EACH ROW EXECUTE FUNCTION core.touch_versioned();
CREATE TRIGGER stock_count_touch BEFORE UPDATE ON inventory.stock_count FOR EACH ROW EXECUTE FUNCTION core.touch_versioned();
CREATE UNIQUE INDEX inventory_item_variant_barcode_uq ON inventory.inventory_item_variant (tenant_id, barcode) WHERE barcode IS NOT NULL;
CREATE INDEX inventory_ledger_entry_grain_ix ON inventory.inventory_ledger_entry (tenant_id, property_id, inventory_item_variant_id, location_id, occurred_at);
CREATE INDEX inventory_ledger_entry_source_ix ON inventory.inventory_ledger_entry (tenant_id, source_document_type, source_document_id);
